CREATE OR REPLACE FUNCTION private.announce_throws(p_round uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  rec public.encounter_players%ROWTYPE;
  who text;
  line text;
  last_line text;
BEGIN
  FOR rec IN
    SELECT ep.*
    FROM public.encounter_players ep
    WHERE ep.round_id = p_round
      AND ep.ball IS NOT NULL
      AND ep.throw_processed = false
    ORDER BY coalesce(private.trainer_label(ep.user_id), 'Trainer'), ep.user_id
    FOR UPDATE
  LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    IF rec.result_reason IS DISTINCT FROM 'standard_throw' THEN
      BEGIN
        PERFORM private.spend_bag_item(rec.user_id, rec.ball);
      EXCEPTION
        WHEN SQLSTATE 'NB001' THEN
          UPDATE public.encounter_players ep
            SET throw_processed = true, result_reason = 'no_ball_left'
            WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
          INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
          SELECT p_round, rec.user_id, who, 'timeout', rec.ball,
                 '⌛ ' || who || ' ran out of ' || private.item_label(rec.ball) || 's before the throw.'
          WHERE NOT EXISTS (
            SELECT 1 FROM public.play_console_log l
            WHERE l.round_id = p_round AND l.user_id = rec.user_id AND l.kind = 'timeout'
          )
          ON CONFLICT DO NOTHING;
          CONTINUE;
      END;
    END IF;
    UPDATE public.encounter_players ep
      SET throw_processed = true
      WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
    line := who || ' has thrown ' || private.a_or_an(private.item_label(rec.ball)) || '!';
    PERFORM private.log_activity(p_round, rec.user_id, 'threw', rec.ball);
    UPDATE public.play_console_log l
      SET message = line
      WHERE l.round_id = p_round
        AND l.user_id = rec.user_id
        AND l.kind = 'threw'
        AND coalesce(l.message, '') = '';
    last_line := line;
  END LOOP;

  FOR rec IN
    SELECT ep.*
    FROM public.encounter_players ep
    WHERE ep.round_id = p_round AND ep.ball IS NULL AND ep.result IS NULL
  LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
    SELECT p_round, rec.user_id, who, 'timeout', NULL,
           '⌛ ' || who || ' did not choose a Poké Ball in time.'
    WHERE NOT EXISTS (
      SELECT 1 FROM public.play_console_log l
      WHERE l.round_id = p_round AND l.user_id = rec.user_id AND l.kind = 'timeout'
    )
    ON CONFLICT DO NOTHING;
  END LOOP;

  RETURN last_line;
END;
$function$

CREATE OR REPLACE FUNCTION private.canonical_form_id(p_dex integer, p_form_id integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  f public.pokemon_forms;
begin
  if p_dex is null or p_dex < 1 then
    raise exception 'Invalid species.';
  end if;
  if p_form_id is null or p_form_id = p_dex then
    if not exists (select 1 from public.pokemon_forms where pokemon_form_id = p_dex and is_base) then
      -- Base row missing: still treat NationalDex as base identity.
      return p_dex;
    end if;
    return p_dex;
  end if;
  select * into f from public.pokemon_forms where pokemon_form_id = p_form_id;
  if f.pokemon_form_id is null then
    raise exception 'Unknown form id %.', p_form_id;
  end if;
  if f.dex is distinct from p_dex then
    raise exception 'Form % does not belong to species %.', p_form_id, p_dex;
  end if;
  return f.pokemon_form_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_ball_modifier(p_ball text, p_dex integer, p_owns_species boolean DEFAULT false, p_at timestamp with time zone DEFAULT now(), p_config jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  cfg jsonb := coalesce(p_config, private.capture_config());
  ctx jsonb := coalesce(cfg->'_context', '{}'::jsonb);
  b public.capture_balls%rowtype;
  s public.species%rowtype;
  mult numeric;
  met boolean := false;
  tier jsonb;
  zone text := coalesce(cfg->>'timezone', 'UTC');
  local_hour int;
  start_hour int;
  end_hour int;
  progress numeric := coalesce((ctx->>'throwProgress')::numeric, 0.5);
  trainer_level int := coalesce((ctx->>'trainerLevel')::int, 1);
  gender text := lower(coalesce(ctx->>'gender', ''));
begin
  if p_ball is null then
    return jsonb_build_object('key', null, 'name', null, 'multiplier', 1.0,
                              'conditionMet', false, 'guaranteed', false, 'condition', 'NONE');
  end if;
  select * into b from public.capture_balls where key = p_ball;
  if not found then
    return jsonb_build_object('key', p_ball, 'name', private.item_label(p_ball), 'multiplier', 1.0,
                              'conditionMet', false, 'guaranteed', false, 'condition', 'UNKNOWN');
  end if;
  select * into s from public.species where dex = p_dex;
  mult := b.base_multiplier;
  case b.condition_type
    when 'TARGET_TYPE' then
      met := coalesce(s.types, '{}'::text[]) && (
        select coalesce(array_agg(value), '{}'::text[])
        from jsonb_array_elements_text(coalesce(b.condition_config->'types', '[]'::jsonb))
      );
    when 'NIGHT' then
      start_hour := coalesce((b.condition_config->>'startHour')::int, 18);
      end_hour := coalesce((b.condition_config->>'endHour')::int, 6);
      local_hour := extract(hour from (p_at at time zone zone))::int;
      met := case
        when start_hour > end_hour then local_hour >= start_hour or local_hour < end_hour
        else local_hour >= start_hour and local_hour < end_hour
      end;
    when 'PLAYER_OWNS_SPECIES' then
      met := coalesce(p_owns_species, false);
    when 'SPECIES_CATCH_RATE_MIN' then
      met := coalesce(s.catch_rate, 0) >= coalesce((b.condition_config->>'min')::int, 999);
    when 'SPECIES_BASE_SPEED_MIN' then
      met := coalesce(s.base_speed, 0) >= coalesce((b.condition_config->>'min')::int, 999);
    when 'MOON_STONE_FAMILY' then
      met := coalesce(s.moon_stone_family, false);
    when 'SPECIES_WEIGHT_TIERS' then
      select t into tier
      from jsonb_array_elements(coalesce(b.condition_config->'tiers', '[]'::jsonb)) t
      where coalesce(s.weight_kg, 0) >= (t->>'minKg')::numeric
      order by (t->>'minKg')::numeric desc
      limit 1;
      if tier is not null then
        met := true;
        mult := (tier->>'multiplier')::numeric;
      end if;
    when 'THROW_EARLY' then
      met := progress <= coalesce((b.condition_config->>'maxProgress')::numeric, 0.34);
    when 'THROW_LATE' then
      met := progress >= coalesce((b.condition_config->>'minProgress')::numeric, 0.66);
    when 'TRAINER_LEVEL_GTE' then
      met := trainer_level >= coalesce((b.condition_config->>'minLevel')::int, 8);
    when 'TARGET_GENDERED' then
      met := gender in ('male', 'female');
    else
      met := false;
  end case;
  if met and b.conditional_multiplier is not null and b.condition_type <> 'SPECIES_WEIGHT_TIERS' then
    mult := b.conditional_multiplier;
  end if;
  return jsonb_build_object(
    'key', b.key, 'name', b.name, 'multiplier', mult,
    'conditionMet', met, 'condition', b.condition_type, 'guaranteed', b.guaranteed_capture
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_chance(p_dex integer, p_ball text, p_berry text DEFAULT NULL::text, p_honey_contributors integer DEFAULT 0, p_honey_participants integer DEFAULT 0, p_contributed_honey boolean DEFAULT false, p_owns_species boolean DEFAULT false, p_is_shiny boolean DEFAULT false, p_other_multiplier numeric DEFAULT 1.0, p_at timestamp with time zone DEFAULT now(), p_config jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  cfg jsonb := coalesce(p_config, private.capture_config());
  s public.species%rowtype;
  base numeric;
  ball jsonb;
  berry jsonb;
  honey jsonb;
  contributor numeric;
  shiny numeric;
  event numeric;
  other numeric := coalesce(p_other_multiplier, 1.0);
  raw numeric;
  final numeric;
  min_chance numeric := coalesce((cfg->>'minChance')::numeric, 0.02);
  max_chance numeric := coalesce((cfg->>'maxChance')::numeric, 0.85);
begin
  select * into s from public.species where dex = p_dex;
  base := private.capture_base_chance(s.catch_rate, cfg);
  ball := private.capture_ball_modifier(p_ball, p_dex, p_owns_species, p_at, cfg);
  berry := private.capture_berry_modifier(p_berry);
  honey := private.capture_honey_modifier(p_honey_contributors, p_honey_participants, cfg);
  contributor := case
    when coalesce(p_contributed_honey, false) then coalesce((cfg->>'honeyContributorBonus')::numeric, 1.0)
    else 1.0
  end;
  shiny := case when coalesce(p_is_shiny, false)
    then coalesce((cfg->>'shinyMultiplier')::numeric, 1.0) else 1.0 end;
  event := coalesce((cfg->>'eventMultiplier')::numeric, 1.0);

  raw := base
       * (ball->>'multiplier')::numeric
       * (berry->>'multiplier')::numeric
       * (honey->>'multiplier')::numeric
       * contributor
       * shiny
       * event
       * other;

  if coalesce((ball->>'guaranteed')::boolean, false) then
    final := 1.0;
  else
    final := least(max_chance, greatest(min_chance, raw));
  end if;

  return jsonb_build_object(
    'dex', p_dex,
    'species', s.name,
    'catchRate', s.catch_rate,
    'baseChance', base,
    'ball', ball,
    'berry', berry,
    'honey', honey,
    'honeyContributorMultiplier', contributor,
    'shinyMultiplier', shiny,
    'eventMultiplier', event,
    'otherMultiplier', other,
    'rawChance', raw,
    'finalChance', final,
    'guaranteed', coalesce((ball->>'guaranteed')::boolean, false),
    'minChance', min_chance,
    'maxChance', max_chance
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_round_context(p_round uuid, p_uid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  r public.encounter_rounds%rowtype;
  ep public.encounter_players%rowtype;
  contributors int;
  participants int;
  owns boolean;
begin
  select * into r from public.encounter_rounds where id = p_round;
  if not found then
    return null;
  end if;
  select * into ep from public.encounter_players where round_id = p_round and user_id = p_uid;
  select count(*)::int, count(*) filter (where prep = 'bait')::int
    into participants, contributors
    from public.encounter_players where round_id = p_round;
  select exists (
    select 1 from public.catches c where c.user_id = p_uid and c.dex = r.dex
  ) into owns;
  return private.capture_chance(
    r.dex,
    ep.ball,
    case when ep.prep = 'bait' then null else ep.prep end,
    contributors,
    participants,
    ep.prep = 'bait',
    owns,
    private.variant_is_shiny(r.variant),
    1.0,
    now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_self_test()
 RETURNS TABLE(name text, passed boolean, detail text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  cfg jsonb := private.capture_config();
  pidgey int := 16;
  vaporeon int := 134;
  caterpie int := 10;
  snorlax int := 143;
  jolteon int := 135;
  clefairy int := 35;
  mewtwo int := 150;
  base numeric;
begin
  base := private.capture_base_chance(255, cfg);

  name := 'Poke Ball is 1.00x';
  passed := (private.capture_chance(pidgey, 'pokeball')->>'finalChance')::numeric = base;
  detail := (private.capture_chance(pidgey, 'pokeball')->>'finalChance');
  return next;

  name := 'Hisui Poke Ball is 1.00x';
  passed := (private.capture_chance(pidgey, 'hisuipokeball')->'ball'->>'multiplier')::numeric = 1.00;
  detail := (private.capture_chance(pidgey, 'hisuipokeball')->'ball'->>'multiplier');
  return next;

  name := 'Great Ball is 1.25x';
  passed := (private.capture_chance(pidgey, 'greatball')->'ball'->>'multiplier')::numeric = 1.25;
  detail := (private.capture_chance(pidgey, 'greatball')->'ball'->>'multiplier');
  return next;

  name := 'Ultra Ball is 1.50x';
  passed := (private.capture_chance(pidgey, 'ultraball')->'ball'->>'multiplier')::numeric = 1.50;
  detail := (private.capture_chance(pidgey, 'ultraball')->'ball'->>'multiplier');
  return next;

  name := 'Master Ball always succeeds';
  passed := (private.capture_chance(mewtwo, 'masterball')->>'finalChance')::numeric = 1.0
        and (private.capture_chance(mewtwo, 'masterball')->>'guaranteed')::boolean;
  detail := (private.capture_chance(mewtwo, 'masterball')->>'finalChance');
  return next;

  name := 'Maximum chance is never exceeded';
  passed := (private.capture_chance(caterpie, 'ultraball', 'goldenrazz', 10, 10, true, true)->>'finalChance')::numeric
            <= coalesce((cfg->>'maxChance')::numeric, 0.85);
  detail := (private.capture_chance(caterpie, 'ultraball', 'goldenrazz', 10, 10, true, true)->>'finalChance');
  return next;

  name := 'Minimum chance is never breached';
  passed := (private.capture_chance(mewtwo, 'beastball')->>'finalChance')::numeric
            >= coalesce((cfg->>'minChance')::numeric, 0.02);
  detail := (private.capture_chance(mewtwo, 'beastball')->>'finalChance');
  return next;

  name := 'Net Ball helps against Water types';
  passed := (private.capture_chance(vaporeon, 'netball')->'ball'->>'multiplier')::numeric = 1.55;
  detail := (private.capture_chance(vaporeon, 'netball')->'ball'->>'multiplier');
  return next;

  name := 'Net Ball helps against Bug types';
  passed := (private.capture_chance(caterpie, 'netball')->'ball'->>'multiplier')::numeric = 1.55;
  detail := (private.capture_chance(caterpie, 'netball')->'ball'->>'multiplier');
  return next;

  name := 'Net Ball does nothing against unrelated types';
  passed := (private.capture_chance(pidgey, 'netball')->'ball'->>'multiplier')::numeric = 1.00;
  detail := (private.capture_chance(pidgey, 'netball')->'ball'->>'multiplier');
  return next;

  name := 'Repeat Ball checks species ownership';
  passed := (private.capture_chance(pidgey, 'repeatball', null, 0, 0, false, true)->'ball'->>'multiplier')::numeric = 1.55
        and (private.capture_chance(pidgey, 'repeatball', null, 0, 0, false, false)->'ball'->>'multiplier')::numeric = 1.00;
  detail := (private.capture_chance(pidgey, 'repeatball', null, 0, 0, false, true)->'ball'->>'multiplier');
  return next;

  name := 'Dusk Ball uses the game timezone';
  passed := (private.capture_chance(pidgey, 'duskball', null, 0, 0, false, false, false, 1.0,
               (current_date + time '23:00') at time zone coalesce(cfg->>'timezone', 'UTC'))->'ball'->>'multiplier')::numeric = 1.50
        and (private.capture_chance(pidgey, 'duskball', null, 0, 0, false, false, false, 1.0,
               (current_date + time '12:00') at time zone coalesce(cfg->>'timezone', 'UTC'))->'ball'->>'multiplier')::numeric = 1.00;
  detail := coalesce(cfg->>'timezone', 'UTC');
  return next;

  name := 'Fast Ball checks base speed';
  passed := (private.capture_chance(jolteon, 'fastball')->'ball'->>'multiplier')::numeric = 1.55
        and (private.capture_chance(snorlax, 'fastball')->'ball'->>'multiplier')::numeric = 1.00;
  detail := (private.capture_chance(jolteon, 'fastball')->'ball'->>'multiplier');
  return next;

  name := 'Heavy Ball scales with weight';
  passed := (private.capture_chance(snorlax, 'heavyball')->'ball'->>'multiplier')::numeric = 1.55
        and (private.capture_chance(pidgey, 'heavyball')->'ball'->>'multiplier')::numeric = 1.00;
  detail := (private.capture_chance(snorlax, 'heavyball')->'ball'->>'multiplier');
  return next;

  name := 'Moon Ball uses evolution metadata';
  passed := (private.capture_chance(clefairy, 'moonball')->'ball'->>'multiplier')::numeric = 1.60
        and (private.capture_chance(pidgey, 'moonball')->'ball'->>'multiplier')::numeric = 1.00;
  detail := (private.capture_chance(clefairy, 'moonball')->'ball'->>'multiplier');
  return next;

  name := 'Nest Ball checks canonical catch rate';
  passed := (private.capture_chance(caterpie, 'nestball')->'ball'->>'multiplier')::numeric = 1.45
        and (private.capture_chance(vaporeon, 'nestball')->'ball'->>'multiplier')::numeric = 1.00;
  detail := (private.capture_chance(caterpie, 'nestball')->'ball'->>'multiplier');
  return next;

  name := 'Berry modifier is applied once';
  passed := abs((private.capture_chance(pidgey, 'pokeball', 'razz')->>'rawChance')::numeric - base * 1.15) < 0.000001;
  detail := (private.capture_chance(pidgey, 'pokeball', 'razz')->>'rawChance');
  return next;

  name := 'Unreleased Berries do not apply';
  passed := (private.capture_chance(pidgey, 'pokeball', 'figy')->'berry'->>'multiplier')::numeric = 1.0;
  detail := (private.capture_chance(pidgey, 'pokeball', 'figy')->'berry'->>'multiplier');
  return next;

  name := 'Honey modifier is applied once';
  passed := abs((private.capture_chance(pidgey, 'pokeball', null, 6, 10)->>'rawChance')::numeric - base * 1.10) < 0.000001;
  detail := (private.capture_chance(pidgey, 'pokeball', null, 6, 10)->>'rawChance');
  return next;

  name := 'Honey does not scale infinitely';
  passed := (private.capture_chance(pidgey, 'pokeball', null, 100, 100)->'honey'->>'multiplier')::numeric
            = (private.capture_chance(pidgey, 'pokeball', null, 10, 10)->'honey'->>'multiplier')::numeric;
  detail := (private.capture_chance(pidgey, 'pokeball', null, 100, 100)->'honey'->>'multiplier');
  return next;

  name := 'Zero Honey is 1.00x';
  passed := (private.capture_chance(pidgey, 'pokeball', null, 0, 12)->'honey'->>'multiplier')::numeric = 1.0;
  detail := (private.capture_chance(pidgey, 'pokeball', null, 0, 12)->'honey'->>'multiplier');
  return next;

  name := 'Full Honey participation uses the configured maximum';
  passed := (private.capture_chance(pidgey, 'pokeball', null, 12, 12)->'honey'->>'multiplier')::numeric
            = coalesce((select (t->>'multiplier')::numeric from jsonb_array_elements(cfg->'honeyTiers') t
                        where (t->>'minRate')::numeric >= 1), 1.22);
  detail := (private.capture_chance(pidgey, 'pokeball', null, 12, 12)->'honey'->>'multiplier');
  return next;

  name := 'Non contributors still get the community bonus';
  passed := (private.capture_chance(pidgey, 'pokeball', 'razz', 6, 10, false)->'honey'->>'multiplier')::numeric > 1.0
        and (private.capture_chance(pidgey, 'pokeball', 'razz', 6, 10, false)->>'honeyContributorMultiplier')::numeric = 1.0;
  detail := (private.capture_chance(pidgey, 'pokeball', 'razz', 6, 10, false)->>'honeyContributorMultiplier');
  return next;

  name := 'Contributors get the personal bonus';
  passed := (private.capture_chance(pidgey, 'pokeball', null, 6, 10, true)->>'honeyContributorMultiplier')::numeric
            = coalesce((cfg->>'honeyContributorBonus')::numeric, 1.03);
  detail := (private.capture_chance(pidgey, 'pokeball', null, 6, 10, true)->>'honeyContributorMultiplier');
  return next;

  name := 'Shiny modifier defaults to 1.00x';
  passed := (private.capture_chance(pidgey, 'pokeball', null, 0, 0, false, false, true)->>'finalChance')::numeric
            = (private.capture_chance(pidgey, 'pokeball')->>'finalChance')::numeric;
  detail := (private.capture_chance(pidgey, 'pokeball', null, 0, 0, false, false, true)->>'shinyMultiplier');
  return next;

  name := 'Female variants use the species base rate';
  passed := private.capture_base_chance((select catch_rate from public.species where dex = 29))
            = private.capture_base_chance((select catch_rate from public.species where dex = 32));
  detail := (select catch_rate::text from public.species where dex = 29);
  return next;

  name := 'Two Trainers roll independently';
  passed := private.secure_random() <> private.secure_random();
  detail := 'distinct secure rolls';
  return next;

  name := 'One capture row per Trainer per encounter';
  passed := exists (select 1 from pg_indexes where indexname = 'capture_log_once_idx');
  detail := 'capture_log_once_idx';
  return next;

  name := 'Duplicate throws cannot spend two Poke Balls';
  passed := exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'encounter_players' and column_name = 'throw_processed'
  );
  detail := 'encounter_players.throw_processed';
  return next;

  name := 'Berries are never treated as throwable Poke Balls';
  passed := not private.is_throw_ball('razz') and not private.is_throw_ball('goldenrazz')
        and private.is_throw_ball('ultraball');
  detail := 'razz, goldenrazz';
  return next;

  name := 'Spec example: catch rate 45 with Ultra, Razz and 60 percent Honey';
  passed := abs((private.capture_chance(vaporeon, 'ultraball', 'razz', 6, 10)->>'finalChance')::numeric - 0.2087) < 0.0005;
  detail := (private.capture_chance(vaporeon, 'ultraball', 'razz', 6, 10)->>'finalChance');
  return next;

  name := 'Spec example: catch rate 3 with Ultra, Golden Razz, full Honey';
  passed := abs((private.capture_chance(mewtwo, 'ultraball', 'goldenrazz', 10, 10, true)->>'finalChance')::numeric - 0.0980) < 0.0005;
  detail := (private.capture_chance(mewtwo, 'ultraball', 'goldenrazz', 10, 10, true)->>'finalChance');
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_throw_context(p_round encounter_rounds, p_uid uuid, p_ball_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  prepare_at timestamptz;
  throw_at timestamptz;
  used timestamptz := coalesce(p_ball_at, now());
  progress numeric := 0.5;
  lvl int := 1;
  g text := '';
begin
  if p_round.deadlines is not null then
    prepare_at := (p_round.deadlines->>'prepare')::timestamptz;
    throw_at := coalesce((p_round.deadlines->>'throw')::timestamptz, (p_round.deadlines->>'reveal')::timestamptz);
    if prepare_at is not null and throw_at is not null and throw_at > prepare_at then
      progress := extract(epoch from (used - prepare_at)) / extract(epoch from (throw_at - prepare_at));
    end if;
  end if;
  select private.trainer_level(xp) into lvl from public.profiles where id = p_uid;
  g := coalesce(p_round.gender, '');
  return jsonb_build_object('throwProgress', progress, 'trainerLevel', coalesce(lvl, 1), 'gender', g);
end;
$function$

CREATE OR REPLACE FUNCTION private.form_display_name(p_dex integer, p_form_id integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  f public.pokemon_forms;
  species_name text;
  fid int;
begin
  select name into species_name from public.species where dex = p_dex;
  species_name := coalesce(species_name, 'Pokémon');
  fid := private.canonical_form_id(p_dex, p_form_id);
  select * into f from public.pokemon_forms where pokemon_form_id = fid;
  if f.pokemon_form_id is null or f.is_base then
    return species_name;
  end if;
  return species_name || ' — ' || f.form_label;
end;
$function$

CREATE OR REPLACE FUNCTION private.materialize_streamlink_catch(p_user_id uuid, p_form_id integer, p_level integer, p_ctx text, p_source_key text, p_ball text DEFAULT 'poke'::text, p_round_id uuid DEFAULT NULL::uuid, p_shiny boolean DEFAULT false, p_content_build text DEFAULT 'sl-ref-20261013-227b573'::text, p_hidden_ticket text DEFAULT NULL::text, p_variant text DEFAULT 'normal'::text, p_name text DEFAULT NULL::text, p_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_dex int;
  v_name text;
  inserted uuid;
  v_public text;
BEGIN
  IF private.streamlink_wire_is_enabled() THEN
    RETURN private.persist_streamlink_catch(
      p_user_id, p_form_id, p_level, p_ctx, p_source_key, p_ball, p_round_id,
      p_shiny, p_content_build, p_hidden_ticket, p_variant, p_name, p_gender
    );
  END IF;

  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-user'), 'path', 'stamp');
  END IF;
  IF p_ctx IS NULL OR p_ctx NOT IN ('catch', 'grant', 'event') THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-ctx'), 'path', 'stamp');
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-source-key'), 'path', 'stamp');
  END IF;
  IF p_ctx IN ('grant', 'event') AND private.streamlink_protected_trainer(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('protected-trainer'), 'path', 'stamp');
  END IF;

  SELECT f.dex, initcap(replace(s.slug, '-', ' '))
    INTO v_dex, v_name
  FROM private.ref_forms f
  JOIN private.ref_species s
    ON s.content_build = f.content_build AND s.dex = f.dex
  WHERE f.content_build = coalesce(p_content_build, 'sl-ref-20261013-227b573')
    AND f.form_id = p_form_id;
  v_dex := coalesce(v_dex, p_form_id);
  v_name := coalesce(nullif(btrim(p_name), ''), v_name, 'Pokemon');

  BEGIN
    INSERT INTO public.catches (
      user_id, dex, name, variant, gender, ball, round_id, source_key, level, pokemon_form_id
    ) VALUES (
      p_user_id,
      v_dex,
      v_name,
      coalesce(nullif(btrim(p_variant), ''), 'normal'),
      coalesce(nullif(btrim(p_gender), ''), 'M'),
      coalesce(nullif(btrim(p_ball), ''), 'poke'),
      p_round_id,
      p_source_key,
      p_level,
      p_form_id
    )
    RETURNING id, public_id INTO inserted, v_public;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array('already-settled'),
      'replay', true,
      'path', 'stamp'
    );
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'catchId', inserted,
    'publicId', v_public,
    'path', 'stamp'
  );
END
$function$

CREATE OR REPLACE FUNCTION private.round_phase(r encounter_rounds)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  clk timestamptz;
begin
  if r is null or r.cancelled then
    return 'closed';
  end if;
  if not private.deadlines_complete(r.deadlines) then
    return coalesce(nullif(r.phase, ''), 'closed');
  end if;
  clk := coalesce(r.paused_at, now());
  return case
    when clk < (r.deadlines->>'join')::timestamptz then 'join'
    when clk < (r.deadlines->>'prepare')::timestamptz then 'prepare'
    when clk < (r.deadlines->>'throw')::timestamptz then 'throw'
    when clk < (r.deadlines->>'reveal')::timestamptz then 'reveal'
    else 'closed'
  end;
end;
$function$

CREATE OR REPLACE FUNCTION private.settle_if_needed(r encounter_rounds)
 RETURNS encounter_rounds
 LANGUAGE plpgsql
AS $function$
DECLARE
  rec public.encounter_players%ROWTYPE;
  cfg jsonb;
  calc jsonb;
  bait_count int;
  player_count int;
  owns boolean;
  v_odds numeric;
  v_roll numeric;
  v_caught boolean;
  pending boolean;
  clk timestamptz;
  join_at timestamptz;
  prepare_at timestamptz;
  throw_at timestamptz;
  reveal_at timestamptz;
  throw_line text;
  who text;
  species text;
  test_out text;
  form_id int;
  v_level int;
  v_mat jsonb;
  v_catch_id uuid;
  v_life text;
BEGIN
  IF r IS NULL OR r.cancelled THEN RETURN r; END IF;
  IF r.paused_at IS NOT NULL THEN RETURN r; END IF;
  IF NOT pg_try_advisory_xact_lock(hashtextextended(r.id::text, 0)) THEN RETURN r; END IF;
  SELECT * INTO r FROM public.encounter_rounds WHERE id = r.id;
  IF r IS NULL OR r.cancelled OR r.paused_at IS NOT NULL THEN RETURN r; END IF;
  SELECT EXISTS (SELECT 1 FROM public.encounter_players ep WHERE ep.round_id = r.id AND ep.result IS NULL) INTO pending;
  IF pending = false AND r.resolved THEN RETURN r; END IF;
  clk := now();
  form_id := private.canonical_form_id(r.dex, coalesce(r.pokemon_form_id, r.dex));
  species := coalesce(nullif(btrim(r.name), ''), private.form_display_name(r.dex, form_id), 'the Pokémon');
  IF r.deadlines IS NOT NULL THEN
    join_at := (r.deadlines->>'join')::timestamptz;
    prepare_at := (r.deadlines->>'prepare')::timestamptz;
    throw_at := coalesce((r.deadlines->>'throw')::timestamptz, (r.deadlines->>'reveal')::timestamptz);
    reveal_at := (r.deadlines->>'reveal')::timestamptz;
  END IF;
  IF join_at IS NOT NULL AND clk >= join_at THEN
    IF NOT EXISTS (SELECT 1 FROM public.encounter_players WHERE round_id = r.id) THEN
      INSERT INTO public.play_console_log (round_id, kind, message)
      SELECT r.id, 'cancelled', 'No Trainers joined the encounter. The wild ' || species || ' wandered away!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.kind = 'cancelled')
      ON CONFLICT DO NOTHING;
      UPDATE public.encounter_rounds SET cancelled = true, hidden = true, phase = 'closed', resolved = true, paused_at = null,
        last_action = 'No Trainers joined. The wild ' || species || ' wandered away!', updated_at = now() WHERE id = r.id RETURNING * INTO r;
      RETURN r;
    END IF;
    PERFORM private.phase_banner(r.id, 'prepare', 'Trainers are preparing their items…');
  END IF;
  IF prepare_at IS NOT NULL AND clk >= prepare_at THEN
    PERFORM private.phase_banner(r.id, 'throw', 'Trainers are choosing their Poké Balls!');
  END IF;
  IF r.deadlines IS NOT NULL THEN
    IF throw_at IS NOT NULL AND clk < throw_at THEN RETURN r; END IF;
  ELSIF private.round_phase(r) IN ('join', 'prepare', 'throw') THEN
    RETURN r;
  END IF;
  throw_line := private.announce_throws(r.id);
  IF throw_line IS NOT NULL THEN
    UPDATE public.encounter_rounds SET last_action = throw_line, updated_at = now() WHERE id = r.id RETURNING * INTO r;
  END IF;
  IF reveal_at IS NOT NULL AND clk < reveal_at THEN RETURN r; END IF;
  IF r.deadlines IS NULL AND private.round_phase(r) = 'reveal' THEN RETURN r; END IF;
  cfg := private.capture_config();
  test_out := CASE
    WHEN coalesce(r.trigger_source, '') = 'TEST' THEN nullif(btrim(coalesce(r.rules->>'testOutcome', '')), '')
    ELSE NULL
  END;
  SELECT count(*)::int, count(*) FILTER (WHERE prep = 'bait')::int INTO player_count, bait_count FROM public.encounter_players WHERE round_id = r.id;
  FOR rec IN SELECT * FROM public.encounter_players WHERE round_id = r.id AND result IS NULL FOR UPDATE LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    IF rec.ball IS NULL OR rec.result_reason = 'no_ball_left' THEN
      UPDATE public.encounter_players ep SET result = 'No throw', caught = false, result_reason = coalesce(ep.result_reason, 'no_ball')
      WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
      CONTINUE;
    END IF;
    SELECT EXISTS (SELECT 1 FROM public.catches c WHERE c.user_id = rec.user_id AND c.dex = r.dex) INTO owns;
    cfg := private.capture_config() || jsonb_build_object(
      '_context', private.capture_throw_context(r, rec.user_id, rec.ball_at)
    );
    calc := private.capture_chance(r.dex, rec.ball, CASE WHEN rec.prep = 'bait' THEN NULL ELSE rec.prep END, bait_count, player_count, rec.prep = 'bait', owns, private.variant_is_shiny(r.variant), 1.0, clk, cfg);
    v_odds := (calc->>'finalChance')::numeric;
    IF test_out = 'catch' THEN
      v_roll := 0; v_caught := true;
    ELSIF test_out = 'escape' THEN
      v_roll := 1; v_caught := false;
    ELSIF coalesce((calc->>'guaranteed')::boolean, false) THEN
      v_roll := 0; v_caught := true;
    ELSE
      v_roll := private.secure_random(); v_caught := v_roll < v_odds;
    END IF;
    UPDATE public.encounter_players ep SET chance = v_odds, roll = v_roll, caught = v_caught, result = CASE WHEN v_caught THEN 'Caught' ELSE 'Escaped' END, result_reason = CASE WHEN v_caught THEN 'caught' ELSE 'escaped' END WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
    INSERT INTO public.capture_log (round_id, user_id, dex, species_name, variant, gender, is_shiny, is_female, canonical_catch_rate, base_chance, ball_key, ball_multiplier, ball_condition_met, berry_key, berry_multiplier, honey_contributors, honey_participants, honey_multiplier, honey_contributor_multiplier, shiny_multiplier, event_multiplier, other_multiplier, raw_chance, final_chance, capture_roll, success, detail)
    VALUES (r.id, rec.user_id, r.dex, r.name, r.variant, r.gender, private.variant_is_shiny(r.variant), r.gender = 'Female', (calc->>'catchRate')::int, (calc->>'baseChance')::numeric, calc->'ball'->>'key', (calc->'ball'->>'multiplier')::numeric, (calc->'ball'->>'conditionMet')::boolean, calc->'berry'->>'key', (calc->'berry'->>'multiplier')::numeric, (calc->'honey'->>'contributors')::int, (calc->'honey'->>'participants')::int, (calc->'honey'->>'multiplier')::numeric, (calc->>'honeyContributorMultiplier')::numeric, (calc->>'shinyMultiplier')::numeric, (calc->>'eventMultiplier')::numeric, (calc->>'otherMultiplier')::numeric, (calc->>'rawChance')::numeric, v_odds, v_roll, v_caught, calc || jsonb_build_object('testOutcome', test_out, 'formId', form_id))
    ON CONFLICT (round_id, user_id) DO NOTHING;
    IF v_caught THEN
      INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
      SELECT r.id, rec.user_id, who, 'caught', species, '⭐ ' || who || ' caught ' || species || '!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.user_id = rec.user_id AND l.kind = 'caught') ON CONFLICT DO NOTHING;
    ELSE
      INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
      SELECT r.id, rec.user_id, who, 'escaped', species, '✖ ' || who || ' was unable to catch ' || species || '. Better luck next encounter!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.user_id = rec.user_id AND l.kind = 'escaped') ON CONFLICT DO NOTHING;
    END IF;
    IF v_caught AND NOT EXISTS (SELECT 1 FROM public.catches c WHERE c.round_id = rec.round_id AND c.user_id = rec.user_id) THEN
      v_level := coalesce(private.encounter_pokemon_level(r.dex, r.id), 5);
      v_mat := private.materialize_streamlink_catch(
        rec.user_id,
        form_id,
        v_level,
        'catch',
        'play:' || rec.round_id::text || ':' || rec.user_id::text,
        rec.ball,
        rec.round_id,
        private.variant_is_shiny(r.variant),
        'sl-ref-20261013-227b573',
        NULL,
        r.variant,
        species,
        r.gender
      );
      IF coalesce(v_mat->>'ok', 'false') IS DISTINCT FROM 'true' THEN
        IF coalesce((v_mat->>'replay')::boolean, false)
           OR coalesce(v_mat->'errors', '[]'::jsonb) ? 'already-settled' THEN
          IF NOT EXISTS (
            SELECT 1 FROM public.catches c
            WHERE c.round_id = rec.round_id AND c.user_id = rec.user_id
          ) THEN
            RAISE EXCEPTION 'wire-materialize-failed: already-settled-without-catch';
          END IF;
        ELSE
          RAISE EXCEPTION 'wire-materialize-failed: %', coalesce(v_mat->>'errors', v_mat::text);
        END IF;
      END IF;
      IF coalesce(v_mat->>'ok', 'false') = 'true' THEN
        BEGIN
          v_catch_id := NULL;
          v_life := NULL;
          IF nullif(btrim(v_mat->>'catchId'), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            v_catch_id := (v_mat->>'catchId')::uuid;
          END IF;
          IF v_catch_id IS NOT NULL THEN
            SELECT a.lifecycle INTO v_life
            FROM private.species_mastery_activation AS a
            WHERE a.singleton
            FOR SHARE;
            IF v_life IN ('active', 'paused') THEN
              PERFORM private.note_species_mastery_catch(v_catch_id);
            END IF;
          END IF;
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
      END IF;
    END IF;
  END LOOP;
  UPDATE public.encounter_rounds SET resolved = true, paused_at = null, last_action = coalesce(throw_line, last_action, 'Results locked in'), updated_at = now() WHERE id = r.id RETURNING * INTO r;
  RETURN r;
END;
$function$

CREATE OR REPLACE FUNCTION private.spend_bag_item(p_uid uuid, p_item text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  spent int;
BEGIN
  IF p_item = 'berry' THEN
    UPDATE public.inventories SET berry = berry - 1, updated_at = now()
      WHERE user_id = p_uid AND berry > 0;
  ELSIF p_item = 'bait' THEN
    UPDATE public.inventories SET bait = bait - 1, updated_at = now()
      WHERE user_id = p_uid AND bait > 0;
  ELSIF p_item = 'pokeball' THEN
    UPDATE public.inventories SET pokeball = pokeball - 1, updated_at = now()
      WHERE user_id = p_uid AND pokeball > 0;
  ELSIF p_item = 'greatball' THEN
    UPDATE public.inventories SET greatball = greatball - 1, updated_at = now()
      WHERE user_id = p_uid AND greatball > 0;
  ELSIF p_item = 'ultraball' THEN
    UPDATE public.inventories SET ultraball = ultraball - 1, updated_at = now()
      WHERE user_id = p_uid AND ultraball > 0;
  ELSIF private.is_capture_berry(p_item) THEN
    UPDATE public.inventories
      SET berries = jsonb_set(
            coalesce(berries, '{}'::jsonb),
            ARRAY[p_item],
            to_jsonb(coalesce((berries->>p_item)::int, 0) - 1)
          ),
          updated_at = now()
      WHERE user_id = p_uid
        AND coalesce((berries->>p_item)::int, 0) > 0;
  ELSIF p_item = ANY (private.extra_ball_keys()) THEN
    UPDATE public.inventories
      SET balls = jsonb_set(
            coalesce(balls, '{}'::jsonb),
            ARRAY[p_item],
            to_jsonb(coalesce((balls->>p_item)::int, 0) - 1)
          ),
          updated_at = now()
      WHERE user_id = p_uid
        AND coalesce((balls->>p_item)::int, 0) > 0;
  ELSE
    RAISE EXCEPTION 'Unknown item.';
  END IF;
  GET DIAGNOSTICS spent = ROW_COUNT;
  IF spent = 0 THEN
    RAISE EXCEPTION 'You have no % left. No item spent.', private.item_label(p_item)
      USING ERRCODE = 'NB001';
  END IF;
  INSERT INTO public.item_ledger (user_id, item_key, amount, reason, source_id, idempotency)
  VALUES (
    p_uid, p_item, -1, 'BAG_SPEND', NULL,
    'bag-spend:' || p_uid::text || ':' || p_item || ':' || gen_random_uuid()::text
  );
END;
$function$

CREATE OR REPLACE FUNCTION private.stamp_catch_server_inserted_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  NEW.server_inserted_at := clock_timestamp();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.trainer_level(p_xp integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  cap int := greatest(1, least(coalesce((private.progression_config()->>'maxLevel')::int, 100), 200));
  xp int := greatest(coalesce(p_xp, 0), 0);
  lvl int := 1;
begin
  while lvl < cap and xp >= private.xp_to_reach_level(lvl + 1) loop
    lvl := lvl + 1;
  end loop;
  return lvl;
end;
$function$

CREATE OR REPLACE FUNCTION private.xp_to_reach_level(p_level integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  total int := 0;
  i int;
  cap int := greatest(1, least(coalesce((private.progression_config()->>'maxLevel')::int, 100), 200));
  target int := greatest(1, least(coalesce(p_level, 1), cap));
begin
  if target <= 1 then
    return 0;
  end if;
  for i in 1 .. target - 1 loop
    total := total + private.xp_for_level(i);
  end loop;
  return total;
end;
$function$
